public class FitnessFunction_isFeasible_TriageGen0Test {

    private CMAESOptimizer.FitnessFunction fitnessFunction;

    @Before
    public void setUp() {
        fitnessFunction = new CMAESOptimizer.FitnessFunction();
    }

    /**
     * Helper method to set the private 'boundaries' field via reflection
     * to test the null branch.
     */
    private void setBoundaries(Object target, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField("boundaries");
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testIsFeasible_BoundariesIsNull() throws Exception {
        // Given: boundaries is null
        setBoundaries(fitnessFunction, null);
        double[] x = {0.5, 0.5};

        // When & Then: Should return true immediately
        assertTrue("Should return true when boundaries is null", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_AllValuesWithinRange() throws Exception {
        // Given: boundaries is not null (simulated by providing a dummy value if possible, 
        // but since the code only checks for null, any non-null object works)
        // However, based on the provided snippet, 'boundaries' is a field in FitnessFunction.
        // We assume it's an object. We'll use an empty array or similar if it's an array.
        setBoundaries(fitnessFunction, new double[]{0, 1});
        double[] x = {0.0, 0.5, 1.0};

        // When & Then: Should return true
        assertTrue("Should return true when all values are between 0 and 1", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_ValueTooLow() throws Exception {
        // Given
        setBoundaries(fitnessFunction, new double[]{0, 1});
        double[] x = {0.5, -0.1, 0.5};

        // When & Then: Should return false because -0.1 < 0
        assertFalse("Should return false when a value is less than 0", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_ValueTooHigh() throws Exception {
        // Given
        setBoundaries(fitnessFunction, new double[]{0, 1});
        double[] x = {0.5, 1.1, 0.5};

        // When & Then: Should return false because 1.1 > 1.0
        assertFalse("Should return false when a value is greater than 1.0", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_EmptyArray() throws Exception {
        // Given
        setBoundaries(fitnessFunction, new double[]{0, 1});
        double[] x = {};

        // When & Then: Loop doesn't execute, should return true
        assertTrue("Should return true for an empty array", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_BoundaryValues() throws Exception {
        // Given
        setBoundaries(fitnessFunction, new double[]{0, 1});
        double[] x = {0.0, 1.0};

        // When & Then: Should return true (0.0 is not < 0 and 1.0 is not > 1.0)
        assertTrue("Should return true for exact boundary values 0.0 and 1.0", fitnessFunction.isFeasible(x));
    }
}
